template.script:
{
    "@context": "https://schema.org",
    "@type": "WebSite",
    "name": "ChaosHub.lk",
    "url": "https://chaoshub.lk",
    "description": "Engineering Clarity from Chaos - Knowledge hub for ERP, accounting, and business management.",
    "publisher": {
        "@type": "Organization",
        "name": "ChaosHub"
    },
    "potentialAction": {
        "@type": "SearchAction",
        "target": "https://chaoshub.lk/knowledge?search={search_term_string}",
        "query-input": "required name=search_term_string"
    }
}
